        bool beforeDigit = true;
        while (userInput > 0)
        {
            int currentDigit = (userInput % 10);
            if (beforeDigit && currentDigit != 0)
            {
                beforeDigit = false;
            }

            if (!beforeDigit || currentDigit != 0)
            {
                printf("%d", currentDigit);
            }
            userInput /= 10;
        }
        printf("\n");
    }
    else
    {
        printf("Error in input!\n");
    }

    return 0;
}

