int main(void)
{
    char originalWord[WORD_SIZE] = {0}, secretSentence[SENTENCE_SIZE];

    // input:
    fgets(secretSentence, SENTENCE_SIZE, stdin);
    fgets(originalWord, WORD_SIZE, stdin);

    // putting an end of string character at the end of a string
    int k = 0;
    while (k < WORD_SIZE && originalWord[k] != '\n')
    {
        k++;
    }
    originalWord[k] = '\0';

    k = 0;
    while (k < SENTENCE_SIZE && secretSentence[k] != '\n')
    {
        k++;
    }
    secretSentence[k] = ' ';

    // finding the key:
    int key = GET_KEY(secretSentence[0], originalWord[0]), current = 1;
    for (int i = 1; i < SENTENCE_SIZE; i++)
    {
        if (secretSentence[i] == ' ')
        {
            while (secretSentence[i] == ' ')
            {
                i++;
            }

            current = 0;
            key = GET_KEY(secretSentence[i], originalWord[current]);
            current++;
            i++;
        }

        int letter = originalWord[current] + key;
        if (letter > 'z')
        {
            letter -= 26;
        }
        if (letter == secretSentence[i])
        {
            current++;

            if (current == WORD_SIZE || originalWord[current] == '\0')
            {
                break;
            }
        }
        else
        {
            while (i < SENTENCE_SIZE && secretSentence[i] != ' ')
            {
                i++;
            }
            i--;
        }
    }

    printf("%d", key);

    return 0;
}

